WITH lines AS (SELECT id, service, level, latency_ms, key, value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, value) SELECT CASE WHEN latency_ms >= 2194 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, key, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN level = 'ERROR' THEN 1 END), 0), 2) AS latency_ms_per_error, COUNT(DISTINCT level) AS distinct_levels FROM lines GROUP BY latency_ms_tier, key HAVING ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN level = 'ERROR' THEN 1 END), 0), 2) > 0
